test('addLine adds a new line to an invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  const invoiceWithNewLine = addLine(result.value, { sku: 'STICKER', qty: 10 });

  assert.equal(invoiceWithNewLine.ok, true);
  assert.equal(invoiceWithNewLine.value.lines.length, 2);
  assert.equal(invoiceWithNewLine.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(invoiceWithNewLine.value.lines[1].sku, 'STICKER');
  assert.equal(invoiceWithNewLine.value.lines[1].qty, 10);
  assert.equal(invoiceWithNewLine.value.lines[1].name, 'Sticker sheet');
